      box-shadow: 0 16px 34px rgba(37, 99, 235, 0.28);
    }

    button[type="submit"]:focus-visible,
    .option__control:focus-visible {
      outline: 3px solid #111827;
      outline-offset: 3px;
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    @media (max-width: 480px) {
      .card__header,
      .card__body {
        padding-left: 1.25rem;
        padding-right: 1.25rem;
      }

      .form-field {
        padding: 1rem;
      }
