      left: 1rem;
      top: 1rem;
      z-index: 1000;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--surface);
      color: var(--text);
      text-decoration: none;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      box-shadow: var(--shadow);
    }

