    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
    }

    button[type="submit"] {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.3rem;
      background: linear-gradient(180deg, var(--accent), var(--accent-strong));
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.24);
