   <a class="skip-link" href="#maincontent">Skip to main content</a>

   <main id="maincontent" tabindex="-1">
     <section class="card" aria-labelledby="page-title">
       <header class="card__header">
         <p class="eyebrow">Preferences</p>
         <h1 id="page-title">Choose how you want to hear from us</h1>
       </header>

       <div class="card__body">
         <form id="notification-form" novalidate>
           <div class="form-field">
             <fieldset aria-describedby="notification-help">
               <legend>
                 How do you prefer to receive notifications?
                 <span class="required" aria-hidden="true">*</span>
               </legend>
               <p class="hint" id="notification-help">Select one option before continuing.</p>

               <div class="options">
                 <label class="option" for="notification-email">
                   <input class="option__control" type="radio" id="notification-email" name="notifications" value="email" required>
                   <span class="option__content">
                     <span class="option__label">Email</span>
                     <span class="option__meta">Best for detailed updates and receipts.</span>
                   </span>
                 </label>

                 <label class="option" for="notification-sms">
                   <input class="option__control" type="radio" id="notification-sms" name="notifications" value="sms" required>
                   <span class="option__content">
                     <span class="option__label">SMS</span>
                     <span class="option__meta">Great for quick alerts on your phone.</span>
                   </span>
                 </label>

                 <label class="option" for="notification-push">
                   <input class="option__control" type="radio" id="notification-push" name="notifications" value="push" required>
                   <span class="option__content">
                     <span class="option__label">Push Notifications</span>
                     <span class="option__meta">Ideal for instant in-app or browser updates.</span>
                   </span>
                 </label>
               </div>
             </fieldset>
           </div>

           <div class="actions">
             <button type="submit">Save preferences</button>
             <p class="status" id="form-status" aria-live="polite"></p>
           </div>
         </form>
       </div>
     </section>
   </main>

   <script>
     const form = document.getElementById('notification-form');
     const status = document.getElementById('form-status');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       if (!form.checkValidity()) {
         form.reportValidity();
         const firstInvalid = form.querySelector('input[type="radio"]:invalid');
         if (firstInvalid) {
           firstInvalid.focus();
         }
         status.textContent = '';
         return;
       }

       const selected = form.elements.notifications.value;
       const labels = {
         email: 'Email',
         sms: 'SMS',
         push: 'Push Notifications'
       };

       status.textContent = `Preferences saved. We'll send notifications by ${labels[selected]}.`;
     });
   </script>
 </body>
 </html>

